import{z as i,x as s,o,c as p,q as A,j as n,D as B,d as e,s as r,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"太大而不能倒","description":"","frontmatter":{"title":"太大而不能倒","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/too-big-to-fail.md","filePath":"econ/too-big-to-fail.md","lastUpdated":1791413859000}'),d={name:"econ/too-big-to-fail.md"};function T(F,E,D,h,m,g){const t=s("Mermaid");return o(),p("div",null,[E[2]||(E[2]=A('<h1 id="太大而不能倒" tabindex="-1">太大而不能倒 <a class="header-anchor" href="#太大而不能倒" aria-label="Permalink to &quot;太大而不能倒&quot;">​</a></h1><div class="epigraph"><p>若市场相信某家机构倒闭的社会成本不可接受，对该机构负债的担保就不必写在任何保单上。</p><footer>—— 据 Stern and Feldman, Too Big to Fail: The Hazards of Bank Bailouts, Brookings Institution Press, 2004 整理</footer></div><p>定位：<a href="/econ/lender-of-last-resort">上一课</a>。Bagehot 已经把窗口限制在好抵押与惩罚利率上，并把偿付能力问题交给处置。本课缺口是系统性机构的<strong>隐担保</strong>：规模、关联、不可替代的功能使市场相信股东与无保险债权人也会被保住。不重列三句规则，不把隐担保写成存款保险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最后贷款人删的是流动性坏均衡，筛选靠抵押。若机构大到处置会中断支付、冻结银行间网络、或触发上一课尚未写尽的传染，事后最优往往是连资不抵债也救。事前，债权人把这一事后最优写进价格：资金成本下降，杠杆与风险上升。Stern 与 Feldman 把这种信念称为太大而不能倒（TBTF）。</p><p>缺口不是「危机里要不要救」，而是：隐担保如何改变平时的资本结构，以及它与 Bagehot 的哪一句冲突。冲突点明确——好抵押要求资不抵债走处置；TBTF 说处置不可信。</p><p><span class="marginnote">TBTF 不是资产负债表的一个科目。它是均衡信念：无保险负债的信用利差里已经扣除了预期救助。利差变窄是证据的候选，不是定义本身。</span></p><p><span class="marginnote">术语翻译：「隐担保」就是没有写进任何合同、但市场人人相信政府会兜底的保证——它不出现在费率表或保单里，却实实在在写进了债券的价格与银行的融资成本里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把担保分成三层，已经出场的两层不再展开。零售<a href="/econ/deposit-insurance">存款保险</a>是显式、有上限的保单。Bagehot 窗口是显式、有抵押的流动性。TBTF 是对<strong>未保险、无抵押、甚至股权</strong>的预期转移支付。它不出现在费率表里，出现在债权人愿意接受的更薄利差、以及经理更愿意保留的尾部风险。</p><p>对照 Bagehot。自由放贷针对好抵押上的流动性；惩罚利率阻止把窗口当日常资本；好抵押把资不抵债剔出窗口。TBTF 反过来：数量上可能无上限，价格上可能接近市场而非惩罚，抵押上可能接受已经减值的资产——因为「不救」的社会成本被写成不可接受。时间不一致在<a href="/econ/time-inconsistency">承诺</a>课已经有一般形式；这里的具体对象是处置的不可信。</p>',11)),(o(),n(l,null,{default:B(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E8%A7%84%E6%A8%A1%E6%88%96%E4%B8%8D%E5%8F%AF%E6%9B%BF%E4%BB%A3%E5%8A%9F%E8%83%BD%22%5D%20--%3E%20BELIEF%5B%22%E5%B8%82%E5%9C%BA%3A%20%E5%A4%84%E7%BD%AE%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20BELIEF%20--%3E%20SPREAD%5B%22%E6%97%A0%E4%BF%9D%E9%99%A9%E8%B4%9F%E5%80%BA%E5%88%A9%E5%B7%AE%E5%8F%98%E7%AA%84%22%5D%0A%20%20SPREAD%20--%3E%20LEV%5B%22%E7%A7%81%E4%BA%BA%E6%9D%A0%E6%9D%86%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BAGEHOT%5B%22Bagehot%3A%20%E5%A5%BD%E6%8A%B5%E6%8A%BC%2C%20%E6%83%A9%E7%BD%9A%E5%88%A9%E7%8E%87%22%5D%20--%3E%20RESOLVE%5B%22%E8%B5%84%E4%B8%8D%E6%8A%B5%E5%80%BA%E8%B5%B0%E5%A4%84%E7%BD%AE%22%5D%0A%20%20BELIEF%20--%3E%20CONFLICT%5B%22%E4%B8%8E%E5%A4%84%E7%BD%AE%E6%89%BF%E8%AF%BA%E5%86%B2%E7%AA%81%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"政策含义先停在机制：要恢复 Bagehot，必须使处置可置信——损失能落在无保险债权和股权上，功能能继续。具体的遗嘱、自救债工具是监管后文，本课不列条款。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("机制是社会成本与私人成本的缺口被债权人提前资本化。倒闭的外部性——支付中断、"),a("a",{href:"/econ/bank-contagion"},"传染"),e("、火售——进入事后救助的目标函数，不进入该机构股东的目标函数。债权人若分享事后救助，事前就按准政府信用放贷。于是 TBTF 机构的私人 \\(D^\\ast\\) 更高，与后课权衡里「银行私人杠杆偏高」是同一外部性，只是这里的通道是"),a("strong",null,"资金价格"),e("，不是税盾。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：可以把它想象成家长对不同孩子的态度——小儿子摔跤让他自己爬起来，大儿子一摔全家都要扶。大儿子深知这一点，于是行事更莽撞。「大」本身就换来了一份没人签字的保险。")],-1)),(o(),n(l,null,{default:B(()=>[r(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIG%5B%22%E6%9C%BA%E6%9E%84%E8%A7%84%E6%A8%A1%E5%A4%A7%20%2F%20%E5%85%B3%E8%81%94%E5%BC%BA%22%5D%20--%3E%20EXT%5B%22%E5%80%92%E9%97%AD%E5%A4%96%E9%83%A8%E6%80%A7%3A%20%E6%94%AF%E4%BB%98%E4%B8%AD%E6%96%AD%20%2F%20%E4%BC%A0%E6%9F%93%20%2F%20%E7%81%AB%E5%94%AE%22%5D%0A%20%20EXT%20--%3E%20EXP%5B%22%E5%B8%82%E5%9C%BA%E9%A2%84%E6%9C%9F%3A%20%E5%80%92%E9%97%AD%E6%97%B6%E4%BC%9A%E8%A2%AB%E6%95%91%22%5D%0A%20%20EXP%20--%3E%20SPREAD%5B%22%E6%97%A0%E4%BF%9D%E9%99%A9%E8%B4%9F%E5%80%BA%E5%88%A9%E5%B7%AE%E5%8F%98%E8%96%84%22%5D%0A%20%20SPREAD%20--%3E%20LEV%5B%22%E7%A7%81%E4%BA%BA%E6%9D%A0%E6%9D%86%E4%B8%8E%E5%B0%BE%E9%83%A8%E9%A3%8E%E9%99%A9%E4%B8%8A%E5%8D%87%22%5D%0A%20%20LEV%20--%3E%20FAIL%5B%22%E5%8D%B1%E6%9C%BA%E4%B8%AD%E6%9B%B4%E5%8F%AF%E8%83%BD%E9%99%B7%E5%85%A5%E5%9B%B0%E5%A2%83%22%5D%0A%20%20FAIL%20--%3E%20BAILOUT%5B%22%E4%BA%8B%E5%90%8E%E6%9C%80%E4%BC%98%3A%20%E6%95%91%E5%8A%A9%22%5D%0A%20%20BAILOUT%20-.-%3E%7C%22%E6%95%91%E5%8A%A9%E8%AF%81%E5%AE%9E%E4%BF%A1%E5%BF%B5%22%7C%20EXP%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p><span class="marginnote">常见误区：初学者容易以为 TBTF 是监管机构颁发的优惠名单。实际上它是债权人定价出来的均衡信念——同一家机构哪怕没上任何清单，只要市场相信「倒了会救」，融资成本就会系统性更便宜。</span></p><p>与保险的差别：保险覆盖集是公开的，看跌的标的是被保险存款；TBTF 的覆盖集是博弈结果，标的可以包括批发债甚至股权。Keeley 的特许权价值在这里被另一块租金替换：太小的机构没有这块隐租金，竞争条件不对称。</p><h3 id="救助窗口不是最后贷款人" tabindex="-1">救助窗口不是最后贷款人 <a class="header-anchor" href="#救助窗口不是最后贷款人" aria-label="Permalink to &quot;救助窗口不是最后贷款人&quot;">​</a></h3><p>把股权价值保全写成「流动性支持」，直接破坏 Bagehot 第三句。本课要能把两句话分开：对有偿付能力机构按折扣放贷，是 LOLR；对资不抵债机构的注资或债务担保，是财政或有。混用使惩罚利率失去筛选，使「太大」成为最便宜的融资策略。</p><p><span class="marginnote">跨境机构使「谁的最后贷款人」与「谁的纳税人」错位。本币窗口救不了外币批发债，隐担保若以外币计，还要回到储备与互换，不能用一句 TBTF 跨币种使用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把所有危机救助都贴上 TBTF：针对市场功能的证券购买、针对支付系统的流动性，可以不保全某家股东。也不要把「系统重要性」清单当成已经解决信念——清单本身可能强化隐担保，除非配上可置信的损失吸收。</p><p>本课不写巴塞尔公式。下一课才把亏损顺序写成可审计比率；资本是对 TBTF 激励的数量阀，不是对 Bagehot 三句的改写。</p><p>后课默认：TBTF 是处置不可信时的隐担保，降低无保险负债成本，与 Bagehot 的好抵押冲突。流动性窗口不是保全股权。资本监管下一课才出场。</p><p>规模通过外部性进入事后目标，通过利差进入事前杠杆。两者必须分开写，才能对着干。</p><p>隐担保的覆盖集是均衡，不是保单。不要把它写成存款保险的一个档位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bagehot 要求资不抵债走处置；TBTF 是处置不可信时的隐担保。</li><li>信念被写进无保险负债的价格，私人杠杆系统性偏高。</li><li>保全股权的「流动性支持」不是最后贷款人。</li><li>出处：Stern and Feldman, <em>Too Big to Fail</em>, 2004；对照 Bagehot, <em>Lombard Street</em>。</li></ul>',13))])}const u=i(d,[["render",T]]);export{c as __pageData,u as default};
